"""测试实际C传输代码，链接本地libusb替身；不访问设备。"""
import argparse, ast, json, subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--reference',type=Path,help='可选：另行对照外部工具的纯请求构建函数');p.add_argument('--usb-include',type=Path,required=True);a=p.parse_args()
 out=ROOT/'outputs/usb-verification';out.mkdir(parents=True,exist_ok=True)
 # Fixed independently recorded request, not generated by the C code under test.
 fixture=json.loads((ROOT/'CodeTests/Fixtures/usb-shell-request.json').read_text())
 request=bytes.fromhex(fixture['hex']);assert len(request)==fixture['length']==257
 if a.reference:
  tree=ast.parse(a.reference.read_text());names={'crc16_xmodem','build_factory_shell_request'}
  nodes=[n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name in names]
  constants={}
  for n in tree.body:
   if isinstance(n,ast.Assign):
    for t in n.targets:
     if isinstance(t,ast.Name) and t.id.startswith('FACTORY_') and isinstance(n.value,ast.Constant) and isinstance(n.value.value,int):constants[t.id]=n.value.value
  import struct
  namespace=dict(constants,struct=struct,UsbFactoryError=ValueError)
  exec(compile(ast.Module(body=nodes,type_ignores=[]),'<pure external packet builders>','exec'),namespace)
  assert namespace['build_factory_shell_request'](fixture['command'],fixture['cookie'])==request
 golden=out/'request.bin';golden.write_bytes(request)
 exe=out/'usb-transport-tests'
 subprocess.run(['clang','-Wall','-Wextra','-Werror','-fsanitize=address,undefined','-g','-I'+str(a.usb_include),'-I'+str(ROOT/'native'),str(ROOT/'native/USBBridge.c'),str(ROOT/'CodeTests/USBTransportTests.c'),'-lz','-o',str(exe)],check=True)
 run=subprocess.run([str(exe),str(golden)],capture_output=True,text=True,check=True);print(run.stdout,end='')
 assert 'PASS: 20 transport cases' in run.stdout
 bridge=out/'bridge.o';stub=out/'stub.o';integration=out/'usb-swift-tests'
 for source,target,extra in [(ROOT/'native/USBBridge.c',bridge,[]),(ROOT/'CodeTests/USBTransportTests.c',stub,['-DSC_TEST_EMBED'])]:
  subprocess.run(['clang','-c','-I'+str(a.usb_include),'-I'+str(ROOT/'native'),*extra,str(source),'-o',str(target)],check=True)
 subprocess.run(['swiftc','-swift-version','5','-O','-module-cache-path',str(out/'module-cache'),'-import-objc-header',str(ROOT/'CodeTests/USBTestBridge.h'),'-Xcc','-I'+str(ROOT/'native'),str(ROOT/'native/Core.swift'),str(ROOT/'native/Transport.swift'),str(ROOT/'CodeTests/USBIntegrationTests.swift'),str(bridge),str(stub),'-lz','-o',str(integration)],check=True)
 result=subprocess.run([str(integration),str(golden)],capture_output=True,text=True,check=True);print(result.stdout,end='')
 assert 'PASS: 11 Swift/C' in result.stdout
 (out/'report.json').write_text(json.dumps(dict(cases=20,swiftIntegrationCases=11,passed=True,deviceAccessed=False,reference='fixed offline protocol fixture',externalReferenceChecked=a.reference is not None,addressSanitizer=True,undefinedBehaviorSanitizer=True),indent=2)+'\n')
if __name__=='__main__':main()
